"""Original, task-specific teaching for the forty offline Python exercises.

This authoring source deliberately keeps demonstrations smaller than complete
exercise solutions. Every displayed demonstration has an independently written
expected stdout, checked by tests/test_mobile_python_teaching.py.
"""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]


def primer(name, explanation, example):
    return {"name": name, "explanation": explanation, "example": example}


PRIMERS = {
    "function": primer("Функция: вход, вычисление, выход", "Функция — именованный фрагмент программы. def задаёт её имя и параметры; аргументы подставляются при вызове. return передаёт результат вызывающему коду и завершает именно этот вызов. print только показывает текст и не заменяет return. Имя параметра существует внутри вызова. Отступ объединяет строки тела функции.", "def double(number):\n    return number * 2\n\nanswer = double(4)  # answer равно 8"),
    "values": primer("Значения, типы и присваивание", "str хранит текст, int — целое число, float — дробное, bool — True или False. None означает отсутствие результата по принятому соглашению. Знак = связывает имя со значением; == сравнивает значения; != означает «не равно». Python различает число 12 и строку '12'. int('12') преобразует допустимую десятичную строку в число.", "text = '12'\nnumber = int(text)\nnumber == 12  # True\ntext == 12    # False"),
    "list": primer("Список, позиция и длина", "Список хранит последовательность элементов и сохраняет их порядок; повторы разрешены. [] — пустой список. Позиции начинаются с 0: values[0] — первый элемент, values[-1] — последний. len(values) сообщает количество. append(x) добавляет один элемент в существующий список; его результат не нужно присваивать обратно списку.", "values = ['a', 'b']\nvalues.append('c')\n# values теперь ['a', 'b', 'c']; len(values) равно 3"),
    "dict": primer("Словарь: ключ → значение", "dict связывает уникальный ключ с его значением: это не список позиций. В {'north': 3} ключ — строка 'north', значение — число 3. Чтение d[key] требует существующего ключа. Запись d[key] = value добавляет ключ или заменяет прежнее значение. Проверка key in d смотрит на ключи. d.get(key, default) возвращает default при отсутствии ключа, не добавляя его.", "counts = {}\ncounts['oak'] = 1\ncounts['oak'] = counts.get('oak', 0) + 1\n# counts == {'oak': 2}; 'oak' in counts — True"),
    "branch": primer("Условия и порядок проверок", "if выполняет блок, когда условие истинно. elif проверяется, если предыдущие условия не сработали; else покрывает оставшийся случай. and требует истинности обеих частей, or — хотя бы одной, not меняет истину на ложь. Проверки выполняются слева направо с коротким замыканием: после False в and правая часть уже не вычисляется. Ранний return позволяет сразу закончить недопустимый случай.", "def classify(value):\n    if value < 0 or value > 10:\n        return 'outside'\n    return 'inside'\n\nclassify(4)  # 'inside'"),
    "loop": primer("Цикл, счётчик и остановка", "for item in values берёт элементы по одному. enumerate(values) даёт пары (индекс, элемент); enumerate(values, 1) начинает нумерацию с 1. range(stop) выдаёт целые от 0 до stop, не включая stop; range(start, stop, step) задаёт начало и шаг. continue пропускает остаток текущего шага, break завершает цикл. while повторяет блок, пока условие истинно; состояние должно меняться, чтобы цикл закончился.", "total = 0\nfor index, value in enumerate([4, 7]):\n    total += value  # то же, что total = total + value\n# total равно 11; последний index равен 1"),
    "strings": primer("Строковые методы", "Метод вызывается через точку у объекта: text.split('|', 1). split делит строку; второй аргумент ограничивает число разделений. isdecimal() проверяет, состоит ли непустая строка только из десятичных цифр; знак минус и точка не подходят. strip() убирает пробельные символы с краёв. separator.join(parts) соединяет строки указанным разделителем. Эти методы создают результат, исходную строку не меняют.", "'3|left|right'.split('|', 1)  # ['3', 'left|right']\n'03'.isdecimal()  # True\n'-3'.isdecimal()  # False\n'-'.join(['a', 'b'])  # 'a-b'"),
    "set": primer("Множество хранит только уникальные значения", "set удаляет повторы и позволяет проверять принадлежность. Оно не хранит количество повторений и не задаёт нужный порядок вывода. set() — пустое множество, а {} — пустой словарь. add(x) добавляет значение. update(values) добавляет все элементы последовательности. A & B — пересечение: значения, которые есть в обоих множествах. A.issubset(B) проверяет, что каждый элемент A содержится в B.", "seen = set(['a', 'a', 'b'])  # {'a', 'b'}\nseen.add('c')\n{'a', 'x'} & seen  # {'a'}\n{'a'}.issubset(seen)  # True"),
    "sort": primer("Сортировка и ключ сравнения", "sorted(values) возвращает новый список, не меняя вход. Для словаря перебираются его ключи. Строки сравниваются посимвольно в стандартном порядке Python: '10' идёт перед '2'. Для числового порядка сначала нужны числа. key=function задаёт значение для сравнения. Ключ-кортеж сравнивается слева направо: второй элемент разрешает ничью первого. Минус перед числом меняет направление сортировки этой части.", "sorted([('b', 5), ('a', 5), ('c', 2)], key=lambda pair: (-pair[1], pair[0]))\n# [('a', 5), ('b', 5), ('c', 2)]"),
    "comprehension": primer("Создание нового списка или словаря", "[expression for x in values] строит список, вычисляя expression для каждого x. Условие if в конце оставляет только подходящие элементы. {key: value for ...} аналогично строит словарь. Это сокращённая запись обычного for с append или присваиванием ключа; можно выбрать понятный обычный цикл. Вложенные for читаются слева направо, как вложенные циклы.", "doubles = []\nfor x in [2, 5]:\n    doubles.append(x * 2)\n# То же: doubles = [x * 2 for x in [2, 5]]"),
    "tuple": primer("Кортеж, распаковка и срез", "Кортеж tuple — упорядоченная последовательность, элементы которой нельзя заменить по позиции. Пара (start, end) может быть распакована: start, end = pair. Срез values[a:b] берёт позиции от a включительно до b исключительно. values[-n:] берёт последние n элементов, values[::-1] возвращает обратный порядок. Срез списка создаёт новый внешний список.", "start, end = (2, 5)\n['a', 'b', 'c', 'd'][start:end]  # ['c', 'd']\ntuple([4, 6])  # (4, 6)"),
    "copy": primer("Ссылка и копия", "Присваивание second = first не копирует список: оба имени указывают на один объект. list(first), first[:] и first.copy() создают новый внешний список. dict(record) создаёт новый внешний словарь. Это поверхностные копии: вложенные изменяемые объекты остаются общими, если их отдельно не скопировать. Создавай новые вложенные контейнеры там, где условие требует независимых строк или рекурсивной копии.", "first = [1, 2]\nsecond = list(first)\nsecond.append(3)\n# first остаётся [1, 2]"),
    "exception": primer("Неверный параметр и исключение", "raise ValueError('описание') сообщает, что значение аргумента нарушает контракт функции. Это отличается от обычного возвращаемого результата None или False. try запускает блок; except ValueError обрабатывает соответствующее исключение. Исключения, для которых нет подходящего except, передаются вызывающему коду. Не скрывай неожиданные ошибки общим except без причины.", "def positive(x):\n    if x <= 0:\n        raise ValueError('Нужно положительное число')\n    return x"),
    "class": primer("Класс, экземпляр и метод", "Класс описывает объекты с собственным состоянием. Вызов Counter() создаёт экземпляр и вызывает __init__. self внутри метода — тот экземпляр, у которого вызван метод; Python подставляет его автоматически. self.total — поле объекта, total без self — другое имя. Списки и словари для независимых объектов создавай внутри __init__, а не общим изменяемым полем класса.", "class Counter:\n    def __init__(self):\n        self.total = 0\n    def add(self, value):\n        self.total += value\n\na = Counter()\nb = Counter()\na.add(3)  # a.total == 3; b.total == 0"),
    "callable": primer("Функция как значение", "Функцию можно передать аргументом, сохранить в поле и вызвать позже. f передаёт саму функцию, f(x) сразу вызывает её и передаёт результат. lambda x: x + 1 создаёт короткую функцию с одним выражением; эквивалентный def часто легче читать. Объект с нужным методом можно использовать без проверки названия его класса — важен договорённый интерфейс.", "def plus_one(x):\n    return x + 1\n\noperation = plus_one\noperation(4)  # 5\n# operation = plus_one(4) сохранило бы число, не функцию"),
    "generator": primer("Итератор и генератор", "Iterable — объект, из которого можно получать элементы в for. iter(iterable) создаёт итератор, next(iterator) берёт следующий элемент и продвигает его. Однопроходный итератор нельзя считать заново с начала. Функция с yield создаёт генератор: вызов возвращает объект, а выполнение идёт до следующего yield по мере запроса элементов. После конца возникает StopIteration; for обрабатывает его сам.", "def squares():\n    for x in range(3):\n        yield x * x\n\nit = squares()\nnext(it)  # 0\nnext(it)  # 1\nlist(it)  # [4], оставшаяся часть"),
    "deque": primer("Очередь deque", "from collections import deque импортирует двустороннюю очередь. append(x) добавляет справа, popleft() забирает слева. Это удобно, когда обрабатывается самый старый элемент. deque(maxlen=n) автоматически удаляет самый старый элемент при добавлении сверх n. list(queue) и tuple(queue) создают снимок текущего содержимого.", "from collections import deque\nq = deque([1, 2], maxlen=2)\nq.append(3)\nlist(q)  # [2, 3]\nq.popleft()  # 2"),
    "math": primer("Численные операции", "sum(values) складывает числа, min и max выбирают минимум и максимум. x ** 2 означает квадрат, x / y — деление. round(x, digits) округляет число до заданного количества десятичных знаков для показа. Модуль math подключается через import math; math.sqrt(x) вычисляет квадратный корень, math.exp(x) — e в степени x. Перед делением нужно отдельно разобрать возможность нулевого знаменателя. Небольшая погрешность float нормальна; округление для вывода не должно менять промежуточный алгоритм.", "import math\nmath.sqrt(9 + 16)  # 5.0\nsum([2, 3])  # 5\nmax(0, min(10, 14))  # 10"),
    "pairs": primer("Параллельный обход", "zip(left, right) выдаёт пары соответствующих элементов. for a, b in zip(...) распаковывает каждую пару. zip прекращает работу на более коротком входе; здесь совпадение длин явно гарантируется условием. У словаря .items() выдаёт пары ключ-значение, .keys() — ключи, .values() — значения.", "list(zip([0.2, 0.8], [0, 1]))  # [(0.2, 0), (0.8, 1)]\nlist({'x': 2}.items())  # [('x', 2)]"),
    "json": primer("JSON и Python — разные представления", "JSON — текстовый формат обмена. json.loads(text) разбирает строку и возвращает Python-значение; JSON object становится dict, array — list, null — None, true/false — True/False. Некорректный текст вызывает json.JSONDecodeError. json.dumps(value) делает обратное преобразование. Успешный разбор ещё не гарантирует, что нужные ключи и типы соответствуют контракту.", "import json\njson.loads('{\"ok\": true}')  # {'ok': True}\njson.dumps({'ok': True})  # '{\"ok\": true}'"),
    "types": primer("Строгий тип и bool", "isinstance(value, dict) проверяет принадлежность к словарям. type(value) возвращает точный тип. bool в Python является подклассом int: isinstance(True, int) истинно, хотя в контракте число и логический флаг могут означать разное. Для строгого целого используй type(value) is int. Оператор is проверяет тождественность, поэтому для None и объектов типов он уместен; обычные значения сравнивают через ==.", "isinstance(True, int)  # True\ntype(True) is int     # False\ntype(3) is int        # True\nvalue = None\nvalue is None        # проверка отсутствия значения"),
}


